<script setup lang="ts">
import { onUnmounted, ref } from 'vue'
import { api } from '../api'
import type { Attachment, Company } from '../types'
const props = defineProps<{ initialName?: string }>()
const emit = defineEmits<{ created: [company: Company]; cancel: [] }>()
const form = ref({ chinese_name: props.initialName || '', english_name: '', aliases: '', description: '' }); const file = ref<File>(); const preview = ref(''); const error = ref(''); const busy = ref(false); const created = ref<Company>(); const uploadKey = ref(crypto.randomUUID())
function select(event: Event) { const input = event.target as HTMLInputElement; const next = input.files?.[0]; input.value = ''; if (!next) return; if (next.size > 3*1024*1024) { error.value = 'Logo 不得超过 3 MiB'; return }; if (!['image/png','image/jpeg','image/webp'].includes(next.type)) { error.value = '请选择 PNG、JPG 或 WebP 图片'; return }; URL.revokeObjectURL(preview.value); file.value = next; uploadKey.value = crypto.randomUUID(); preview.value = URL.createObjectURL(next); error.value = '' }
async function save() { busy.value = true; error.value = ''; try { if (!created.value) created.value = await api<Company>('/companies', { method: 'POST', body: JSON.stringify(form.value) }); if (file.value) { const data = new FormData(); data.append('company_id', created.value.id); data.append('file', file.value); data.append('client_id', uploadKey.value); data.append('replace_id',created.value.attachments[0]?.id || ''); const attachment = await api<Attachment>('/attachments', { method: 'POST', body: data }); created.value.attachments = [attachment]; file.value = undefined }; emit('created', await api<Company>(`/companies/${created.value.id}`)) } catch (e) { error.value = (created.value ? '公司已创建，Logo 尚未保存，可重试或稍后在公司页补充。' : '') + (e as Error).message } finally { busy.value = false } }
onUnmounted(() => URL.revokeObjectURL(preview.value))
</script>
<template><Teleport to="body"><div class="modal-backdrop" @keydown.esc.stop="!busy && emit('cancel')"><form class="modal" role="dialog" aria-modal="true" aria-labelledby="create-company-title" @submit.stop.prevent="save"><h2 id="create-company-title">创建公司</h2><fieldset :disabled="busy || !!created"><label>公司中文名<input v-model="form.chinese_name" maxlength="160" autofocus /></label><label>公司英文名<input v-model="form.english_name" maxlength="160" /></label><p class="muted">至少填写一个名称，其余内容可后补。</p><label>简称／别名<input v-model="form.aliases" maxlength="2000" /></label><label>公司简介／世界观设定<textarea v-model="form.description" rows="3" maxlength="100000"></textarea></label></fieldset><label>公司 Logo（不超过 3 MiB）<input type="file" accept="image/png,image/jpeg,image/webp" :disabled="busy" @change="select" /></label><img v-if="preview" :src="preview" alt="Logo 预览" class="company-logo-preview" /><p v-if="error" class="error-text" role="alert">{{ error }}</p><div class="modal-actions"><button type="button" class="secondary" :disabled="busy" @click="created ? emit('created',created) : emit('cancel')">{{ created ? '稍后补充 Logo' : '取消' }}</button><button class="primary" :disabled="busy || (!form.chinese_name.trim() && !form.english_name.trim())">{{ busy ? '保存中…' : created ? '重试上传 Logo' : '创建公司' }}</button></div></form></div></Teleport></template>
